quests[31860] = { id = 31860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", completion = "Welcome back, {name}.  It is time to continue your training.", objectives = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
