quests[31886] = { id = 31886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31887] = { id = 31887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", objectives = "Defeat Steven Lisbane in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31888] = { id = 31888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", objectives = "Defeat Steven Lisbane in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31889] = { id = 31889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31890] = { id = 31890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", objectives = "Defeat Steven Lisbane in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31891] = { id = 31891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31892] = { id = 31892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Trainers: Kalimdor", description = "The very same trainers you bested before in Kalimdor have challenged you once more. No doubt they have not forgotten your last victory!\n\nSeek them out and show them your prowess!", objectives = "Defeat Elena Flutterfly, Cassandra Kaboom, Golbo the Great, Zoltan, and Kela Grimtotem in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31893] = { id = 31893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Trainers: Kalimdor", description = "The same five trainers you defeated in Kalimdor have foolishly once more challenged you to battle.\n\nShow them no mercy!", objectives = "Defeat Elena Flutterfly, Cassandra Kaboom, Golbo the Great, Zoltan, and Kela Grimtotem in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31894] = { id = 31894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delicate Balance", description = "The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, {name}.\n\nThe yaungol activity in Townlong is threatening this balance and must be stopped before it is too late.\n\nWe've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it!", completion = "<Orbiss groans at you in agony.>\n\nSo, the shado-pan have sent you to see what the yaungol are doing? Well, do you see?", objectives = "Speak with Orbiss in the Sumprushes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31895] = { id = 31895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Off Dread", description = "It's time we go to the source, {name}!\n\nShado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nSeek out Bowmistress Li atop the Serpent's Spine on the border of Dread Wastes.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31897] = { id = 31897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Trixxy", description = "Word around the master tamers in Kalimdor is you're the new hotshot that's making such a buzz. Why don't you come down to my training grounds in the Ice Thistle Hills in Winterspring so I can show you how it's done?", progress = "You're tougher than you look!", completion = "You really are some sort of hotshot, aren't ya? You won't be so lucky next time!", objectives = "Defeat Stone Cold Trixxy in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31902] = { id = 31902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31903] = { id = 31903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes..\n\nIf you are able to best them, you will be ready to venture further.", objectives = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31904] = { id = 31904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cassandra Kaboom", description = "I've loaded my pets with new gyrotechnic training modules. You're going down!", completion = "I must've converted a line wrong somewhere...", objectives = "Defeat Cassandra Kaboom in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31905] = { id = 31905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grazzle the Great", description = "You're back?! You're just asking to get eaten by a black dragon!", progress = "I've seen better.", completion = "It's like my pretties have lost their will to fight.", objectives = "Defeat Grazzle the Great in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31906] = { id = 31906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kela Grimtotem", description = "You're so bold as to venture into the heart of Grimtotem lands once more to challenge me? You will regret your decision!", progress = "You are a fool. A lucky fool, but still a fool.", completion = "Mark my words, I will defeat you one day soon.", objectives = "Defeat Kela Grimtotem in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31907] = { id = 31907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoltan", description = "With each passing day my power grows. Resistance is futile.", progress = "All hail Zoltan!", completion = "This world is doomed. Why do you continue to try so fervently?", objectives = "Defeat Zoltan in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31908] = { id = 31908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elena Flutterfly", description = "I see you're ready for another bout in the skies. Let's take flight!", progress = "I admire your abilities in combat.", completion = "My flight has come to an end. Victory is yours this day.", objectives = "Defeat Elena Flutterfly in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31909] = { id = 31909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Trixxy", description = "Freeze! You've finally warmed up from our last encounter, have you? Let's change that.", progress = "You show no mercy. I like you.", completion = "You're hot stuff!", objectives = "Defeat Stone Cold Trixxy in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31910] = { id = 31910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "David Kosse", description = "My research has helped my training regimen greatly. I will defeat you this time.", progress = "I see you've worked on your routine as well.", completion = "Perhaps my research is not as complete as I thought.", objectives = "Defeat David Kosse in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31911] = { id = 31911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deiza Plaguehorn", description = "You have not yet turned to the true path of undeath. Perhaps another battle will show you the way.", completion = "Perhaps undeath is not the answer...", objectives = "Defeat Deiza Plaguehorn in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31912] = { id = 31912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kortas Darkhammer", description = "I hear that you fought my fool of a brother. He lost, eh?\n\nLooks like this is my time to shine!", progress = "How do you have such a strong team?", completion = "You're no better than Durin. In it for the glory. Pah!", objectives = "Defeat Kortas Darkhammer in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31913] = { id = 31913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everessa", description = "I believe I'm figuring out the secrets of this place. Soon I will be unstoppable!", completion = "I see you have secrets of your own.", objectives = "Defeat Everessa in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31914] = { id = 31914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durin Darkhammer", description = "My time under the Firelord has prepared me fer anything. Nothing you can throw at me will deter me!", progress = "What realm spawned a fighter of your caliber?", completion = "I'll defeat ye if it's the last thing I ever do. I haven't come this far fer nothin'!", objectives = "Defeat Durin Darkhammer in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31915] = { id = 31915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Lydia Accoste", description = "The master tamers around the Eastern Kingdoms have been talking about you. You think yourself unstoppable? You believe that you are the true grand master?\n\nCome, then, {name}. I await you in Deadwind Pass. Come, and know the crushing defeat that's always been yours.", progress = "Your power is not like the others'...", completion = "I have an eternity to train. I will defeat you!", objectives = "Defeat Lydia Accoste in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31916] = { id = 31916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Lydia Accoste", description = "You wish to face me again? You will regret this decision!", progress = "You are powerful beyond my own belief.", completion = "You continue to reveal your strategies to me. Eventually, your defeat will be certain.", objectives = "Defeat Lydia Accoste in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31917] = { id = 31917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tamer's Homecoming", description = "Yer ready to enter the full circuit of pet battlin', matey. Go back to yer trainer, Mish Burnhep, in Stormwind, and prepare for the adventure of a lifetime!", completion = "I'm so proud of you, {name}. You're ready for the big time!", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31918] = { id = 31918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tamer's Homecoming", description = "If you beat me, then you must be ready for da big time! Go talk to Varzok in Orgrimmar.", completion = "Well done, {name}. You are finally prepared to truly come into your own as a tamer.", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31919] = { id = 31919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31920] = { id = 31920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Antari", description = "I've seen the likes of you before. A young, naive tamer that thinks that they deserve victory handed to them on a silver platter.\n\nWell no more! I will be your reckoning, {class}. I, Bloodknight Antari of Shadowmoon Valley, await the chance to show you how it feels to be obliterated in battle.", progress = "I don't believe it...", completion = "Impossible! I cannot lose!", objectives = "Defeat Bloodknight Antari in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31921] = { id = 31921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31922] = { id = 31922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicki Tinytech", description = "According to my calculations, I have a 32.333% chance of victory. I'll take it!", progress = "I may have made a mistake somewhere...", completion = "I forgot to carry the 1!", objectives = "Defeat Nicki Tinytech in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31923] = { id = 31923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ras'an", description = "You want to fight again? I think I've gotten better!", progress = "If I win, will you take me to visit Stormwind?", completion = "Nice work!", objectives = "Defeat Ras'an in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31924] = { id = 31924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narrok", description = "I wish to do battle once more. These young ones need to grow stronger.", progress = "You are a worthy adversary.", completion = "It would seem that these younglings still have a lot of work to do before they are at full strength. Thank you.", objectives = "Defeat Narrok in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31925] = { id = 31925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morulu The Elder", description = "I have learned much since our last encounter. Do you wish to test your skills once more?", progress = "You are truly wise beyond your years.", completion = "Even I continue to learn from each passing day.", objectives = "Defeat Morulu The Elder in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31926] = { id = 31926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Antari", description = "You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, {race}.", progress = "Your performance is astonishing.", completion = "You are a fool for thinking yourself better than me. I will crush you, I swear it!", objectives = "Defeat Bloodknight Antari in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31927] = { id = 31927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31928] = { id = 31928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Payne", description = "In my opinion, my fellow tamers have been far too lenient on your training.\n\nTrue pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce.\n\nCome to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!", progress = "Perhaps other methods may be useful in certain cases.", completion = "I was wrong about you, {name}. You've earned my respect as one of the finest adversaries I've ever faced. Don't go and think that I'll let you defeat me again next time, though!", objectives = "Defeat Major Payne in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31929] = { id = 31929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31930] = { id = 31930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31931] = { id = 31931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beegle Blastfuse", description = "One of my chickens flew for just a moment yesterday, I swear. We're finally hitting the big time!\n\nOh, you'd like to battle again?", progress = "We still don't have sustained flight, though.", completion = "One day, when we're flying high above you, you'll be the loser!", objectives = "Defeat Beegle Blastfuse in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31932] = { id = 31932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nearly Headless Jacob", description = "Time and time again you defy my wisdom. What is it that brings you back to these woods?\n\nAh, you wish to do battle once more. Very well then.", progress = "Your intentions are clear.", completion = "Your risk has paid its due reward. Now begone!", objectives = "Defeat Nearly Headless Jacob in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31933] = { id = 31933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrut Dragonwaste", description = "You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!", progress = "You...fool.", completion = "I dare you to continue to fight the inevitable. Dragons will once again serve our purposes, and you will fall to my hand in a pet battle. I swear on the Warchief's mantle that it will be so!", objectives = "Defeat Okrut Dragonwaste in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31934] = { id = 31934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutretch", description = "Me like fighting you. You not so easy like the others. We fight again?", progress = "<Gutretch stares at you blankly.>", completion = "Me like fighting you, even if me lose.", objectives = "Defeat Gutretch in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31935] = { id = 31935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Payne", description = "The rebel {class} comes once again to test <his/her> might again that of a Grand Master. Your bravery will be your undoing this time!", progress = "You are a true fighter at heart. I respect that.", completion = "I applaud your tactics, but despise your victory. Well done, {name}.", objectives = "Defeat Major Payne in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31936] = { id = 31936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Jinyu Princess\" Irrigation System", description = "<The back of the box features a caricature of a jinyu maiden surrounded by marketing copy.>\n\n\"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy?\n\nThen it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\"\n\n<It goes on like this for six paragraphs.>", completion = "A sprinkler system? For the farm? Thank you, {name}! We can use this instead of that old watering can.\n\nThe \"Jinyu Princess\" eh? What's up with that?\n\n\n\nAlright, I don't even want to know. I'll get this installed right away!", objectives = "Bring the \"Jinyu Princess\" Irrigation System to Farmer Yoon at Sunsong Ranch or Halfhill market.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31937] = { id = 31937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Thunder King\" Pest Repellers", description = "<An imposing image of a mogu face dominates this box, casting its gaze downward at neatly ordered rows of bold text.>\n\n\"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\"\n\n<The rest of the space is dedicated to cartoon depictions of various insects crying out in lament or fleeing in terror.>", completion = "Pest repellers! You're a genius, {name}! We can finally stop using that ancient bug sprayer.\n\n\n\nAw yeah, Thunder King! That's what I'm talking about!\n\nI'll get this installed right away - those bugs won't know what hit 'em!", objectives = "Bring the \"Thunder King\" Pest Repellers to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31938] = { id = 31938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Earth-Slasher\" Master Plow", description = "<The box art depicts a pandaren farmer of impossible physique standing proudly astride a widening rift in the earth, a mighty plow in his grasp. Cubs wrestle playfully on his shoulders and dangle from his muscular arms.\n\nAt his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.>\n\n\"The Earth-Slasher. Master the land. Master your life.\"", completion = "An Earth-Slasher master plow! I... I never thought I'd get to use one of these. Do you have any idea how much time this will save us?!\n\nI heard if you push the Earth-Slasher through twenty yards of solid rock, you end up with a sandbox and a citation from the Shado-Pan for causing an earthquake scare!\n\nThis is going to be AWESOME.", objectives = "Bring the \"Earth-Slasher\" Master Plow to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31939] = { id = 31939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nMei Mei Ironpaw over at the market is in need of some carrots for her stew. And you know who can grow those carrots? Us!\n\nHow about you show me what you've learned by planting, growing, and harvesting four beds of Juicycrunch Carrots?You will learn:", sourceObjective = "Plant and harvest 4 Juicycrunch Carrots. Juicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and caring for your planting, you must wait until the next day to harvest grown Juicycrunch Carrots.", sourceObjectiveStatus = "unverified-source-field" }
quests[31940] = { id = 31940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Trainers: Pandaria", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four trainers that you must now defeat: Ziggy the Flightless in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "Defeat Ziggy the Flightless, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31941] = { id = 31941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squash Those Foul Odors", description = "Grandpa always said, \"A squash a week, and your tail won't reek.\"\n\n<Yoon subtly sniffs the air.>\n\nYup. I think it's been about a week. Could you help me plant a Jade Squash?", completion = "Well planted, {name}.\n\nNow we play the waiting game...", objectives = "Plant a Jade Squash in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31942] = { id = 31942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Melon Time", description = "<Farmer Yoon looks up at the sky and sniffs the air.>\n\nHmm...\n\n<He licks his paw and holds it up in the air, sticks a toenail into the soil, and then inspects the length of his shadow.>\n\nYup. It's melon time.\n\nCould you grab some seeds and help me plant a Striped Melon?", progress = "Hurry up! Melon time doesn't last forever!", completion = "That was close. We almost missed melon time.", objectives = "Plant a Striped Melon in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31943] = { id = 31943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Which Berries? Witchberries.", description = "That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him.\n\nI think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.", completion = "Alright, witchberries! I can't wait!\n\nBut I'm gonna have to.", objectives = "Plant Witchberries in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31944] = { id = 31944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Complete Your Training: The Final Test", description = "Welcome back, {name}.  The time has come for you to complete the last step of your training.  Head to the Training Grounds for your final test.", progress = "Complete your final test.", completion = "Well done, {name}.  Your training is now complete.  Feel free to return in the future to spar with the masters here to practice what you have learned.", objectives = "Go the the Training Grounds at the Peak of Serenity and complete your final test.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31945] = { id = 31945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow VI: Gina's Vote", description = "My business is doomed! You see all of the Ironpaws at their cooking stations?\n\nTheir tasty dishes draw many of the customers to this market, but they're all out of scallions!\n\nIt may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic.\n\nThis is terrible. I'm not getting another scallion shipment for a week!\n\nWait a second. You're a farmer, aren't you? You think you could help me?", progress = "Don't overlook the scallion. It may be small and innocuous, but it creates truly marvelous flavors.", completion = "Well, I'll be! I've certainly seen larger scallions, but this will do quite nicely. You've just saved our hides, {name}!", objectives = "Plant and harvest 1 Scallion, then deliver 5 Scallions to Gina Mudclaw.\n\nScallion Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Scallions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31946] = { id = 31946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote III: The Great Carrot Caper", description = "Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined!\n\n<Mung-Mung rubs his chin thoughtfully.>\n\nWait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots. Then, we take your carrots and pretend they are Mr. Mudclaw's.\n\nYes!", progress = "Virmens love carrots, but they hate turnips. I hate turnips, too.", completion = "Whoa, these carrots look crunchy and juicy, {name}! Mung-Mung did not know you had such a green thumb.", objectives = "Plant and harvest 2 Juicycrunch Carrots, then deliver 10 Juicycrunch Carrots to Mung-Mung.\n\nJuicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Juicycrunch Carrots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31947] = { id = 31947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote III: Crazy For Cabbage", description = "<Farmer Fung is beaming with a radiant smile.>\n\nThanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt.\n\nThey must be starving, but I don't feed my prize yaks just any regular old grass.\n\nNo sir, they eat only the leafiest green cabbages you can find here in the Valley.\n\nMy stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.", progress = "I have pet nicknames for all of my yaks. There's Hairy, and Shaggy, and Fluffy, and Woolly, and...", completion = "I was expecting cabbages, but not cabbages of this quality! Oh my!\n\nA perfectly round head, large waxy leaves, a perfect gradient of emerald color...\n\n<Farmer Fung takes a bite out of the cabbage.>\n\nMmm, and sweet, crisp flavor! These is a beautiful cabbage, {name}. My yaks will certainly be spoiled by this tasty treat.", objectives = "Plant and harvest 3 Green Cabbages, then deliver 15 Green Cabbages to Farmer Fung.\n\nGreen Cabbage Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Green Cabbages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31948] = { id = 31948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote II: The Sacred Springs", description = "You caught me at a good time, {name}. I was just hankering to make a fresh batch of Witchberry Julep.\n\nHave you ever heard of this wondrous brew?\n\nEach sip takes ten years off your face! How do you think I still look so good?\n\nAnyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north.\n\nI'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.", progress = "The water in this valley flows from the Vale of Eternal Blossoms to the north. It is said that these waters have wondrous, magical properties.", completion = "Found the falls, did you? Oh yes, I see you found the water. Wonderful!", objectives = "Use the Empty Pitcher at the Golden Falls to collect Thousand-Year Water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31949] = { id = 31949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote III: Witchberry Julep", description = "Now that we have the water, I can almost taste the icy cold witchberry julep!\n\nNow, we just need to find ourselves some sweet witchberries.\n\nMy grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere.\n\nSay, do you have any witchberries in the ground this year? How about you bring me some from your farm?\n\nIf your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!", progress = "Hurry it up, will ya? I'm an old woman. I don't have all the time in the world, and I want one more taste of the sauce before I croak!", completion = "<Nana Mudclaw scrutinizes a dark witchberry, then pops it into her mouth. Her face lights up.>\n\nLands alive! I haven't tasted such a sweet, juicy witchberry in years! Why, the only person who could grow berries like these was... Old Yoon, yer friend's grandpa.\n\n<Nana Mudclaw blushes.>\n\nOh that man was such a scamp! I still remember the summer days when we were young, eating these berries by the bushel without a care in the world.\n\nThank you for reminding me of an old friend, {name}.", objectives = "Plant and harvest 3 Witchberries, then deliver 15 Witchberries to Nana Mudclaw.\n\nWitchberry Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Witchberries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31950] = { id = 31950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Move NPCs to Dais" }
quests[31951] = { id = 31951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Aki", description = "You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics.\n\nI now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, {name}, and let us see if you have what it takes to defeat me.", progress = "I have heard much about your techniques. Hopefully that does not alter the outcome of our bout.", completion = "You have emerged victorious. Continue your training and find challenges in other trainers like yourself. The journey is never truly complete.", objectives = "Defeat Aki the Chosen in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31952] = { id = 31952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31953] = { id = 31953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Hyuna", description = "You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.", progress = "You are a noble fighter.", completion = "You are very strong. Will you lend your skills to my efforts?", objectives = "Defeat Hyuna of the Shrines in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31954] = { id = 31954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Mo'ruk", description = "This time I'm gonna do the beating! You watch!", progress = "No! Me win!", completion = "Next time you lose. I'm gonna beatcha!", objectives = "Defeat Mo'ruk in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31955] = { id = 31955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Nishi", description = "My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!", progress = "You're good, I'll give you that.", completion = "Wow! I'm not the only one that's been training!", objectives = "Defeat Farmer Nishi in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31956] = { id = 31956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Yon", description = "If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!", progress = "You fight well, for a {race}.", completion = "Fine. Victory is yours once more. Begone, I have much preparation to do before we meet again.", objectives = "Defeat Courageous Yon in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31957] = { id = 31957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Shu", description = "You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.", progress = "Perhaps your bravery is not as foolish as I had thought.", completion = "In all my time as a grand master I've never faced one as determined as you. The others were right about you. You are a force to be reckoned with.", objectives = "Defeat Wastewalker Shu in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31958] = { id = 31958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Aki", description = "You wish to test yourself against me once more? Very well, let us fight.", progress = "The journey to greatness is never complete.", completion = "You are stronger and your skills more refined. Your journey continues.", objectives = "Defeat Aki the Chosen in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31959] = { id = 31959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Empress' Gambit", description = "Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess.\n\nWe have been fortunate to hold out this long, but we cannot survive a siege of this scale.\n\nWakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons.\n\nI will see you on the battlefield!", objectives = "Report to Malik the Unscathed outside the Heart of Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31960] = { id = 31960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Vote #1 Complete" }
