quests[31965] = { id = 31965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Vote #6 Complete" }
quests[31966] = { id = 31966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Cataclysm", description = "You have defeated Northrend's finest tamers, but you need more preparation before you are ready to face the grand masters of Pandaria. Ready yourself and hone your skills by defeating these elite tamers: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnce you have triumphed over them, you will be ready to journey to Pandaria to face the ultimate challenge.", objectives = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31967] = { id = 31967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Cataclysm", description = "Northrend has fallen to your hand, but you are not yet ready to face the grand masters of Pandaria. Defeat these tamers to harden your will for the coming challenges: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnly by defeating them will you be ready to journey to Pandaria.", objectives = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31968] = { id = 31968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doubt Begins To Surface", description = "The Alliance... so many airships. How can we possibly fight them all? I... don't feel... well...", sourceObjective = "Snap Nazgrim out of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[31969] = { id = 31969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities Tracking" }
quests[31970] = { id = 31970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Obalis", description = "You think yourself ready to challenge Pandaria? You truly believe that you can defeat the most powerful tamers in all of Azeroth?\n\nI shall be the judge of that notion, {race}. Face me atop the Vir'naal Dam in Uldum, and we shall see if you are truly ready.", progress = "I admire your passion, young one.", completion = "I have been proven wrong. You are prepared to face my greaters.", objectives = "Defeat Obalis in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31971] = { id = 31971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Obalis", description = "I see the triumphant tamer returns to again test <himself/herself> against me. Very well. I accept your challenge.", progress = "Defeat is but a path to success.", completion = "By defeating me, I grow stronger. I urge you to be wary during our next encounter.", objectives = "Defeat Obalis in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31972] = { id = 31972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brok", description = "I do not yet understand the plight of these creatures well enough to help them sufficiently. Perhaps another battle would strengthen our bond?", progress = "Battle me for the good of all of Mount Hyjal.", completion = "Even in defeat I feel closer to my pets. Thank you for a worthy skirmish.", objectives = "Defeat Brok in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31973] = { id = 31973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bordin Steadyfist", description = "The natives have taught me the strength of the earth. I know it's unending endurance. Let us battle once more, and you'll see that I'm tougher than ever!", progress = "You think you can handle me?", completion = "No, no, I just messed up. How about another go?", objectives = "Defeat Bordin Steadyfist in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31974] = { id = 31974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goz Banefury", description = "The power of twilight flows through me. I am a god! You have no hope of defeating me!", progress = "Pathetic {race}. Doomed to die powerless to the true rulers of this world.", completion = "You fight with the wrath of my masters. Perhaps you and I aren't so different.", objectives = "Defeat Goz Banefury in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31975] = { id = 31975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!", completion = "Let's see...where to send you next...", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31976] = { id = 31976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Audrey Burnhep, for further guidance.", completion = "Let's see...where to send you next...", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31977] = { id = 31977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Varzok in Orgrimmar and see what's next in your new career as a tamer!", completion = "I've been at work preparing your next set of challenges, {name}. Let us see if you are prepared...", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31978] = { id = 31978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom to deliver our brew when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", completion = "Well, it's not as much as I would have hoped, but it will have to do. I guess there is no sense in cryin' over spilled brew.", objectives = "Find 6 Barrels of Honeybrew in Honeydew Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31979] = { id = 31979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!", sourceObjective = "Report to Audrey Burnhep in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31980] = { id = 31980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Varzok, for further guidance.", completion = "I think I know just the right place to test you next.", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31981] = { id = 31981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exceeding Expectations", description = "Run off to your trainer, Audrey Burnhep, in Stormwind. Perhaps she can find you more...worthwhile...challenges.", completion = "You really beat Grand Master Antari? Wow! I'm going to have to find you some really tough tamers to fight!", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31982] = { id = 31982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exceeding Expectations", description = "Run off to your trainer, Varzok, in Orgrimmar. Perhaps he can find you more... worthwhile... challenges.", completion = "There is only one place to test you next.", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31983] = { id = 31983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brief Reprieve", description = "Well done, for an {race}. Now, get back to Orgrimmar and talk to that brute Varzok. Maybe he can point you somewhere very far away from my family.", completion = "I think I know the next step you ought to take.", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31984] = { id = 31984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brief Reprieve", description = "Well done, well done indeed! If you would, please report to Miss Audrey Burnhep in Stormwind.\n\nOh, and send her my regards. She's a beautiful young woman that could benefit from the company of an accomplished fighter such as myself.", completion = "Payne asked you to court me for him, didn't he? When is he ever going to learn?", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31985] = { id = 31985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Stormwind and have words with Audrey Burnhep. She will guide you further.", completion = "I take it you met Obalis? He's a wonderful fellow, once you get past his rough exterior.", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31986] = { id = 31986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Orgrimmar and have words with Varzok. He will guide you further.", completion = "You are now prepared for a true test of your skill in battle. Are you up to it?", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31987] = { id = 31987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Theramore Launch Event" }
quests[31988] = { id = 31988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Selected Scenario" }
quests[31989] = { id = 31989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Serenity - Complete Your Training", description = "The time has come for you to return to the Peak of Serenity to complete your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", completion = "Welcome back, {name}.  It is time for the final step of your training.", objectives = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31990] = { id = 31990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audrey Burnhep", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n{race}eport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31991] = { id = 31991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Zusshi", description = "I knew you would return to face me once more. Let us see who is truly wiser in the ways of battle.", progress = "Despite my wisdom, you manage to surprise me.", completion = "You are indeed superior. If you would pardon me, I must consult the lake for guidance in my defeat.", objectives = "Defeat Seeker Zusshi in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31998] = { id = 31998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "You have my gratitude, {name}. You've displayed great valor today, and the speed at which you completed the challenge surely will impress your friends and intimidate your foes.", objectives = "Complete the Temple of the Jade Serpent Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31999] = { id = 31999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrim's Command", description = "You have a comfortable base of operations, no Alliance around for miles, and a few Horde veterans by your side. It looks like it's time to start painting this continent red.\n\nGeneral Nazgrim should know where to start.", completion = "We may have won the battle against the Alliance, but we won't get any further with this many jabbering monkeys on our perimeter.\n\nThe hozen are our next target.", objectives = "Report to General Nazgrim at Strongarm Airstrip in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32000] = { id = 32000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "You have my sincerest thanks, {name}. Without fine Stormstout brews to lighten the drudgery of the day, the world would be a dull place indeed.", objectives = "Complete the Stormstout Brewery Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32001] = { id = 32001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "Many blessings upon you, {name}. Driving hatred from this world so quickly deserves rich reward.", objectives = "Complete the Shado-Pan Monastery Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32002] = { id = 32002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "Many thanks, {name}. Your martial prowess is second to none, and your alacrity is sure to strike fear in the hearts of your enemies.", objectives = "Complete the Mogu'shan Palace Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32003] = { id = 32003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "That was a blow well struck, {name}. I've never seen a {class} fell a giant with such speed.", objectives = "Complete the Gate of the Setting Sun Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32004] = { id = 32004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "{name}, that was amazing. Ner'onok is a master tactician, and you schooled him handily.", objectives = "Complete the Siege of Niuzao Temple Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32005] = { id = 32005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", completion = "{name}, you're a stalwart {class}. Your friends and guild mates will surely notice the speed and ferocity with which you conquered the Scarlet Monastery.", objectives = "Complete the Scarlet Monastery Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32006] = { id = 32006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", completion = "Excellent work, {name}. Just the thought of him burning up that beautiful library makes me shudder. Your friends will appreciate the speed with which you dispatched him.", objectives = "Complete the Scarlet Halls Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32007] = { id = 32007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. May the skeletons of the dead remain peaceful now that Gandling no longer seeks to disturb their slumber.", objectives = "Complete the Scholomance Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32008] = { id = 32008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audrey Burnhep", description = "Greetings, {name}! My name is Audrey Burnhep. I've been hearing quite a lot about you recently. You're becoming quite the tamer!\n\nYou should come speak with me in Stormwind. I have connections with some of the finest tamers in all of Azeroth, and I can help you grow even more!", completion = "Ah, you're {name}. Splendid! Let's get to work then, shall we?", objectives = "Report to Audrey Burnhep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32009] = { id = 32009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Lok'tar, {name}. My name is Varzok. I have heard much your accomplishments as a tamer recently, and I would like to introduce you to trainers around Azeroth so that you may further hone your skills.\n\nPlease speak with me in Orgrimmar so that we may begin.", completion = "You must be {name}. Well met. I am Varzok.\n\nI will serve as your contact from here on out.", objectives = "Report to Varzok in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32010] = { id = 32010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", completion = "The Vale is safer now, thanks to you. Now, you must help the Celestials.", objectives = "Earned Revered standing with the Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32011] = { id = 32011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", completion = "The Vale is safer now, thanks to you. Now, you must help the Celestials.", objectives = "Earned Revered standing with the Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32012] = { id = 32012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kovok tracking [GROWING]" }
quests[32016] = { id = 32016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 90 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32017] = { id = 32017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", objectives = "Collect 90 Lesser Charms of Good Fortune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32018] = { id = 32018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Name Was... Stormstout", description = "An unusual pandaren came through town a few days back. He told a better tale than Pan, drank twice as much as Lee, and then beat me up in front of the bar. All while his little niece made fun of us.\n\nIt was awesome.\n\nThey said they were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", completion = "Ha ha! You were sent by Bolo? The \"Keg Mender,\" right? From the Drunken Hozen?\n\nHow is his eye healing? Is his friend still hung over?\n\nAhh... that was an enjoyable evening.", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32019] = { id = 32019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him... Stormstout", description = "Things were not always like this, {race}. Oh no, they were much, much worse. Not three weeks ago, we were under siege by saurok bandits. They stole our jade, befouled our food stores, and terrorized our cubs.\n\nWe needed a hero, and a hero arrived.\n\nHe drove back their forces, defeated their leader, and returned our stolen jade. All he asked in return was a serpent ride for his niece.\n\nI was never able to thank him. If you are headed to the Valley of the Four Winds, would you relay our thanks?", completion = "You come from the Temple of the Jade Serpent? Rain-Zhu sends his thanks?\n\nAi yah... really, that was nothing. I could have defeated that saurok without spilling my beer.\n\nIn fact, I believe I did.", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32020] = { id = 32020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
