quests[32030] = { id = 32030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once in a Hundred Lifetimes", description = "The time has come, wakener.\n\nThe council's power will combine to bring an end to the corrupted empress.\n\nThis ritual has not been witnessed in one hundred of your kind's lifetimes - and never by an outsider.\n\nIn exchange for your deeds on our behalf, I invite you to behold this great moment in our history.", completion = "Your arrival is timely, wakener.\n\nOur ritual is underway.", objectives = "Speak to Klaxxi'va Ik in Klaxxi'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
