quests[32035] = { id = 32035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got Silk?", description = "Strange noises comin' from over at the Silken Fields.\n\nStrange smells, too.\n\nAlmost makes you think that they could use a cash-strapped {class} to complete a few odd jobs for 'em. Make a few pieces of gold.\n\nOr not.", completion = "Greetings, {class}. Welcome to the Silken Fields.", objectives = "Report to Silkmaster Tsai at the Silken Fields in Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
