quests[32038] = { id = 32038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stag Mastery", description = "I always was a fan of a good stag hunt. Stags are tough, fast, and territorial.\n\nThey may be plant eaters but they can give any hunter a run for his money.\n\nEast of here is a whole mess of Wilderland Stags just waiting for a hunter like yourself to give 'em a good run.\n\nHappy hunting.", progress = "How goes the hunt?", completion = "I haven't seen stag hunting this good since Ashenvale.", objectives = "Kill 10 Wilderland Stags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
