quests[32175] = { id = 32175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Pet Battle!", description = "Are you prepared to test the mettle of your pets...?", progress = "My, my. Well done!", completion = "I must say, good show!", objectives = "Defeat Jeremy Feasel in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32181] = { id = 32181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the grace of the crane against the might of the Horde.", objectives = "Bring the Ancient Bloodcrown Crane to Jorn Skyseer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32182] = { id = 32182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the ferocity of the tiger against the might of the Horde.", objectives = "Bring the Krasari Elder to Jorn Skyseer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32183] = { id = 32183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the resilience of the crab against the might of the Horde.", objectives = "Bring the Colossal Viseclaw to Jorn Skyseer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32184] = { id = 32184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the grace of the crane against the glory of the Alliance!", objectives = "Bring the Ancient Bloodcrown Crane to Huntsman Blake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32185] = { id = 32185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the power of the tiger against the glory of the Alliance!", objectives = "Bring the Krasari Elder to Huntsman Blake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32186] = { id = 32186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the stamina of the crab against the glory of the Alliance!", objectives = "Bring the Colossal Viseclaw to Huntsman Blake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[32189] = { id = 32189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shabby New Face", description = "A strange fellow in a pointy hat showed up this morning trying to sell some kinda special seeds. Claimed they were magic.\n\nI welcome a little competition - business is business, after all - but this gentleman had a certain... shabby look to him. Oh, and he stunk somethin' FIERCE.\n\nWould you check up on him, just to make sure he's on the level? He's over there by Jian Ironpaw, making a meal out of the samples.", completion = "AUGHM... nomf... -slurp- mmmf...\n\n<Barnaby looks up from the table, revealing a tangled beard dotted with melon seeds. Juices rush down his chin as he greets you.>\n\nMmf... -cough- A customer! Hello! Name's Fletcher. Barnaby Fletcher - nice to meet you!\n\n<He wipes a hand on his robe before extending it, still visibly sticky and flecked with pulp.>", objectives = "Speak with Barnaby Fletcher in Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
